// panel.v1 — structured hard-surface detail without exposing fragile booleans.
#include "../GeneratorRegistry.h"
#include "../GeneratorSchema.h"
#include "../MeshBuilder.h"
namespace gen {
void registerPanelGenerator(){
 GeneratorInfo info;info.name="panel.v1";info.description="A beveled-looking, inset hard-surface panel made from a recessed face, raised border, grid ribs and optional studs. Use for doors, crates, chests, machinery panels, shields and sci-fi props.";info.polyBudget=2500;
 info.schema=SchemaBuilder().number("width",1.2f,.05f,20,"Panel width in metres.").number("height",1.6f,.05f,20,"Panel height in metres.").number("depth",.12f,.01f,2,"Overall depth in metres.").number("border",.10f,.005f,1,"Raised frame width in metres.").number("inset",.035f,0,.5f,"How far the central face is recessed.").integer("rows",1,1,8,"Number of horizontal framed cells.").integer("columns",1,1,8,"Number of vertical framed cells.").boolean("studs",false,"Add round corner studs.").color("color",glm::vec3(.30f,.34f,.38f),"Base colour, linear RGB.").number("roughness",.52f,0,1,"Surface roughness.").number("metallic",.15f,0,1,"Metalness.").schema();
 info.build=[](const Params&p,uint32_t,std::vector<std::string>&,std::string&){float w=p.num("width",1.2f),h=p.num("height",1.6f),d=p.num("depth",.12f),b=std::min(p.num("border",.1f),std::min(w,h)*.45f),inset=std::min(p.num("inset",.035f),d*.8f);MeshBuilder out;MaterialAsset m;m.id="panel";m.baseColor=glm::vec4(p.color("color"),1);m.roughness=p.num("roughness",.52f);m.metallic=p.num("metallic",.15f);out.beginSubmesh("Panel",m);out.addBox({-w*.5f,0,-d*.5f},{w*.5f,h,d*.5f});const float z=d*.5f-inset;out.addBox({-w*.5f+b,b,z-d*.08f},{w*.5f-b,h-b,z});int rows=p.integer("rows",1),cols=p.integer("columns",1);for(int r=1;r<rows;++r){float y=h*r/rows;out.addBox({-w*.5f+b,y-b*.18f,z},{w*.5f-b,y+b*.18f,z+d*.08f});}for(int c=1;c<cols;++c){float x=-w*.5f+w*c/cols;out.addBox({x-b*.18f,b,z},{x+b*.18f,h-b,z+d*.08f});}if(p.boolean("studs",false)){for(float x:{-w*.5f+b*.65f,w*.5f-b*.65f})for(float y:{b*.65f,h-b*.65f})out.addIcosphere({x,y,z+d*.09f},b*.28f,1);}return out.build();};GeneratorRegistry::instance().registerGenerator(std::move(info));}
} // namespace gen
